using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;using System.Web.Script.Serialization;using EnhancedZune;
class CompletionTests {
 static List<string> passed=new List<string>();static void Check(bool ok,string text){if(!ok)throw new Exception(text);passed.Add(text);Console.WriteLine("PASS "+text);}
 static IEnumerable<Control> All(Control root){foreach(Control c in root.Controls){yield return c;foreach(var child in All(c))yield return child;}}
 static void Capture(SetupForm form,string path){Application.DoEvents();using(Bitmap b=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(b,new Rectangle(0,0,b.Width,b.Height));b.Save(path);}}
 [STAThread]static int Main(string[] args){try{
  Check(CompletionPolicy.MayLaunch(true,"install",false,false),"Launch allowed after successful normal-user install");Check(CompletionPolicy.MayLaunch(true,"repair",false,false),"Launch allowed after successful repair");
  Check(!CompletionPolicy.MayLaunch(false,"install",false,false),"Failure cannot launch Zune");Check(!CompletionPolicy.MayLaunch(true,"restore",false,false),"Restore cannot launch Zune");Check(!CompletionPolicy.MayLaunch(true,"install",true,false),"Restart requirement suppresses launch");Check(!CompletionPolicy.MayLaunch(true,"install",false,true),"Elevated parent cannot launch Zune with an administrator token");
  Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
  using(SetupForm f=new SetupForm(new string[0])){f.PreviewMode=true;f.ShowInTaskbar=false;f.Opacity=0;f.Show();Capture(f,Path.Combine(args[0],"setup-ready.png"));
   f.ShowCompletion("install",@"C:\unused-test-path",false,false);Capture(f,Path.Combine(args[0],"setup-complete.png"));
   var controls=All(f).ToArray();var launch=controls.OfType<CheckBox>().Single(x=>x.Text=="Launch Zune when setup closes");var finish=controls.OfType<Button>().Single(x=>x.Text=="Finish");var heading=controls.OfType<Label>().Single(x=>x.Text=="Installation complete");
   Check(launch.Visible&&launch.Checked&&finish.Visible&&finish.Enabled,"Completion shows a checked launch option and usable Finish button");Check(heading.Font.Bold&&heading.Font.Size>=16&&heading.ForeColor.G>heading.ForeColor.R,"Success text is large, bold and green");launch.Checked=false;Check(!launch.Checked,"Launch option can be unchecked");
   f.Size=f.MinimumSize;Capture(f,Path.Combine(args[0],"setup-complete-minimum.png"));Check(finish.RectangleToScreen(finish.ClientRectangle).Bottom<=f.RectangleToScreen(f.ClientRectangle).Bottom,"Finish remains within minimum-size form");Check(heading.Height>=TextRenderer.MeasureText(heading.Text,heading.Font,new Size(heading.MaximumSize.Width,1000),TextFormatFlags.WordBreak).Height-4,"Completion heading fits");
   f.ShowCompletion("restore",@"C:\unused-test-path",false,false);Check(!launch.Visible,"Restoring hides launch option");Capture(f,Path.Combine(args[0],"setup-restored.png"));
   f.ShowCompletion("install",@"C:\unused-test-path",true,false);Check(!launch.Visible,"Restart result hides launch option");Capture(f,Path.Combine(args[0],"setup-restart.png"));
   f.Stage("Setup did not complete","Review the error below before retrying.","error");Capture(f,Path.Combine(args[0],"setup-error.png"));Check(controls.OfType<Label>().Single(x=>x.Text=="Setup did not complete").ForeColor.R>150,"Failure heading is red");f.Close();
  }
  using(SetupForm f=new SetupForm(new string[0])){f.PreviewMode=true;f.ShowInTaskbar=false;f.Opacity=0;f.Size=f.MinimumSize;f.Show();f.Log("Unrecognized or modified file: ZuneLocalArtistPhotos.dll. This entire error must be readable.\r\nSecond line of diagnostic details.\r\nThird line of diagnostic details.");Capture(f,Path.Combine(args[0],"setup-log-minimum.png"));var box=All(f).OfType<TextBox>().Single(x=>x.Multiline);Check(box.Height>=150&&box.Width>500,"Diagnostic log stays multiline and at least 150 pixels high when completion controls are hidden");Check(box.Bottom<=box.Parent.ClientSize.Height,"Diagnostic log fits inside minimum-size layout");f.Size=new Size(1000,1000);Application.DoEvents();Check(box.Height>150,"Diagnostic log grows with the window");f.Close();}
  using(var f=new WindowsComponentForm(true)){f.ShowInTaskbar=false;f.Opacity=0;f.Show();Application.DoEvents();using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(0,0,b.Width,b.Height));b.Save(Path.Combine(args[0],"windows-components-progress.png"));}f.Close();}
  File.WriteAllText(Path.Combine(args[0],"COMPLETION-RESULTS.json"),new JavaScriptSerializer().Serialize(new{status="passed",tests=passed,zune_launched=false,windows_components_installed=false,scope="Launch-policy decisions and off-screen UI render; preview mode prevents launching any application."}));return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
